mapper.select:
SELECT 


ORDER BY p.update_time DESC, p.id DESC
LIMIT #{limit}

SELECT p.status AS status, COUNT(*) AS cnt
FROM ecom_dev_project p

    p.owner_id = #{q.ownerId}
    AND p.platform = #{q.platform}
    AND p.source = #{q.source}
    AND p.category = #{q.category}

        AND (p.doc_no LIKE CONCAT('%', #{q.keyword}, '%') OR p.name LIKE CONCAT('%', #{q.keyword}, '%')
             OR p.selling_points LIKE CONCAT('%', #{q.keyword}, '%'))


GROUP BY p.status
